CREATE TABLE public.categories(id text PRIMARY KEY, name text NOT NULL UNIQUE, type text NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; CREATE POLICY access ON public.categories FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE TABLE public.suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code bigint GENERATED ALWAYS AS IDENTITY UNIQUE, name text NOT NULL, cnpj text UNIQUE, phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', lead_time integer NOT NULL DEFAULT 0 CHECK(lead_time>=0), payment text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.suppliers TO authenticated; GRANT ALL ON public.suppliers TO service_role;
ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY; CREATE POLICY access ON public.suppliers FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code bigint GENERATED ALWAYS AS IDENTITY UNIQUE, name text NOT NULL, description text NOT NULL DEFAULT '', category_id text NOT NULL REFERENCES public.categories(id), type text NOT NULL CHECK(type IN ('Matéria-prima','Produto acabado','Embalagem','Intermediário')), unit text NOT NULL CHECK(unit IN ('UN','KG','G','L','ML','CX','PCT','SC')), cost numeric NOT NULL DEFAULT 0 CHECK(cost>=0), stock numeric NOT NULL DEFAULT 0 CHECK(stock>=0), minimum numeric NOT NULL DEFAULT 0 CHECK(minimum>=0), maximum numeric NOT NULL DEFAULT 1000 CHECK(maximum>=minimum), reserved numeric NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock), supplier_id uuid REFERENCES public.suppliers(id), lead_time integer NOT NULL DEFAULT 0 CHECK(lead_time>=0), active boolean NOT NULL DEFAULT true, batch numeric NOT NULL DEFAULT 1 CHECK(batch>0));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; CREATE POLICY access ON public.products FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE UNIQUE INDEX product_name_unique ON public.products(lower(trim(name)));
CREATE TABLE public.bom(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id), component_id uuid NOT NULL REFERENCES public.products(id), quantity numeric NOT NULL CHECK(quantity>0), UNIQUE(product_id,component_id), CHECK(product_id<>component_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.bom TO authenticated; GRANT ALL ON public.bom TO service_role;
ALTER TABLE public.bom ENABLE ROW LEVEL SECURITY; CREATE POLICY access ON public.bom FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE TABLE public.demands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL UNIQUE REFERENCES public.products(id), quantity numeric NOT NULL DEFAULT 0 CHECK(quantity>=0), due_date date NOT NULL DEFAULT current_date+7);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.demands TO authenticated; GRANT ALL ON public.demands TO service_role;
ALTER TABLE public.demands ENABLE ROW LEVEL SECURITY; CREATE POLICY access ON public.demands FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id), type text NOT NULL CHECK(type IN ('Compra','Produção')), quantity numeric NOT NULL CHECK(quantity>0), due_date date NOT NULL DEFAULT current_date+7, status text NOT NULL DEFAULT 'Aberta' CHECK(status IN ('Aberta','Concluída','Cancelada')));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY access ON public.orders FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE TABLE public.movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id), quantity numeric NOT NULL CHECK(quantity<>0), type text NOT NULL, responsible text NOT NULL CHECK(length(trim(responsible))>0), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL DEFAULT auth.uid());
GRANT SELECT,INSERT ON public.movements TO authenticated; GRANT ALL ON public.movements TO service_role;
ALTER TABLE public.movements ENABLE ROW LEVEL SECURITY; CREATE POLICY read ON public.movements FOR SELECT TO authenticated USING(true); CREATE POLICY insert_own ON public.movements FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE TABLE public.history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity text NOT NULL, record_id uuid NOT NULL, action text NOT NULL, before_data jsonb, after_data jsonb, user_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.history TO authenticated; GRANT ALL ON public.history TO service_role;
ALTER TABLE public.history ENABLE ROW LEVEL SECURITY; CREATE POLICY read ON public.history FOR SELECT TO authenticated USING(true);
CREATE FUNCTION public.audit_erp() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.history(entity,record_id,action,before_data,after_data,user_id) VALUES(TG_TABLE_NAME,COALESCE(NEW.id,OLD.id),TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END,auth.uid()); RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER product_audit AFTER INSERT OR UPDATE OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.audit_erp();
CREATE TRIGGER supplier_audit AFTER INSERT OR UPDATE OR DELETE ON public.suppliers FOR EACH ROW EXECUTE FUNCTION public.audit_erp();
CREATE TRIGGER bom_audit AFTER INSERT OR UPDATE OR DELETE ON public.bom FOR EACH ROW EXECUTE FUNCTION public.audit_erp();
CREATE FUNCTION public.move_stock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Responsável inválido'; END IF; IF NEW.type NOT IN ('Entrada de compras','Saída para produção','Entrada de produtos fabricados','Perdas e desperdícios','Ajustes de inventário','Devoluções') THEN RAISE EXCEPTION 'Tipo inválido'; END IF; IF NEW.type IN ('Entrada de compras','Entrada de produtos fabricados') AND NEW.quantity<0 OR NEW.type IN ('Saída para produção','Perdas e desperdícios') AND NEW.quantity>0 THEN RAISE EXCEPTION 'Sinal da movimentação inválido'; END IF; UPDATE public.products SET stock=stock+NEW.quantity WHERE id=NEW.product_id AND stock+NEW.quantity>=reserved; IF NOT FOUND THEN RAISE EXCEPTION 'Saldo insuficiente ou quantidade reservada'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stock_movement BEFORE INSERT ON public.movements FOR EACH ROW EXECUTE FUNCTION public.move_stock();
CREATE FUNCTION public.check_bom_cycle() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(763829); IF EXISTS(WITH RECURSIVE chain(id) AS (SELECT NEW.component_id UNION SELECT b.component_id FROM public.bom b JOIN chain c ON b.product_id=c.id WHERE b.id<>NEW.id) SELECT 1 FROM chain WHERE id=NEW.product_id) THEN RAISE EXCEPTION 'A ficha técnica não pode formar um ciclo'; END IF; RETURN NEW; END $$;
CREATE TRIGGER bom_cycle BEFORE INSERT OR UPDATE ON public.bom FOR EACH ROW EXECUTE FUNCTION public.check_bom_cycle();
CREATE FUNCTION public.finish_order(order_id uuid, responsible text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; b record; p public.products; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Conecte-se'; END IF; SELECT * INTO o FROM public.orders WHERE id=order_id FOR UPDATE; IF NOT FOUND OR o.status<>'Aberta' THEN RAISE EXCEPTION 'Ordem indisponível'; END IF; PERFORM id FROM public.products ORDER BY id FOR UPDATE; SELECT * INTO p FROM public.products WHERE id=o.product_id; IF o.type='Produção' THEN IF NOT EXISTS(SELECT 1 FROM public.bom WHERE product_id=o.product_id) THEN RAISE EXCEPTION 'Cadastre a ficha técnica'; END IF; FOR b IN SELECT * FROM public.bom WHERE product_id=o.product_id LOOP INSERT INTO public.movements(product_id,quantity,type,responsible) VALUES(b.component_id,-b.quantity*o.quantity/p.batch,'Saída para produção',responsible); END LOOP; END IF; INSERT INTO public.movements(product_id,quantity,type,responsible) VALUES(o.product_id,o.quantity,CASE WHEN o.type='Compra' THEN 'Entrada de compras' ELSE 'Entrada de produtos fabricados' END,responsible); UPDATE public.orders SET status='Concluída' WHERE id=order_id; END $$;
REVOKE ALL ON FUNCTION public.finish_order(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.finish_order(uuid,text) TO authenticated;
